import { printFoo } from 'foo'
import { printBar } from 'bar'
import { printFar } from 'far'
import { printBaz } from 'baz'
import { gs } from '@servicenow/glide'

export function rule() {
  //foo@1.0.0dep2@1.0.0dep@2.0.0
  gs.addInfoMessage(printFoo())
  //bar@1.0.0dep2@1.0.0dep@2.0.0
  gs.addInfoMessage(printBar())
  //far@1.0.0dep@1.0.0
  gs.addInfoMessage(printFar())
  //baz@1.0.0dep@1.0.0
  gs.addInfoMessage(printBaz())
}
